#include <iostream>

int main() {
    std::cout << "=== 01: Memory Layout, Pointers & References ===\n";

    int val = 42;
    int* ptr = &val; // Pointer: Holds memory address
    int& ref = val;  // Reference: Immutable alias

    *ptr = 100;
    std::cout << "Modified via pointer  : " << val << "\n";

    ref = 200;
    std::cout << "Modified via reference: " << val << "\n";

    // Pointer Arithmetic
    int arr[3] = {10, 20, 30};
    int* pArr = arr;
    std::cout << "Second element via ptr arithmetic: " << *(pArr + 1) << "\n";

    return 0;
}

#include <iostream>

constexpr int factorial(int n) {
    return (n <= 1) ? 1 : n * factorial(n - 1);
}

consteval int square(int n) {
    return n * n; // Must be evaluated at compile-time!
}

int main() {
    std::cout << "=== 02: auto, decltype, constexpr & consteval ===\n";

    auto x = 10; // Inferred as int
    decltype(x) y = 20;

    constexpr int f5 = factorial(5); // Computed at compile-time by compiler
    constexpr int sq = square(4);

    std::cout << "Factorial(5) at compile-time: " << f5 << "\n";
    std::cout << "Square(4) at compile-time   : " << sq << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <string_view>

// Zero-allocation string slice
void printPrefix(std::string_view sv, size_t n) {
    if (n <= sv.size()) {
        std::cout << "Prefix: " << sv.substr(0, n) << "\n";
    }
}

int main() {
    std::cout << "=== 03: std::string vs std::string_view (C++17) ===\n";
    std::string text = "Modern Systems Programming in C++";
    printPrefix(text, 6); // Zero heap allocations!
    return 0;
}

#include <iostream>
