#include <iostream>
#include <memory>

struct Resource {
    Resource() { std::cout << "Resource Allocated\n"; }
    ~Resource() { std::cout << "Resource Destroyed (RAII Safe)\n"; }
    void use() { std::cout << "Using Resource...\n"; }
};

int main() {
    std::cout << "=== 06: RAII & Smart Pointers (unique_ptr, shared_ptr) ===\n";

    // unique_ptr: Exclusive ownership (Zero overhead)
    std::unique_ptr<Resource> res = std::make_unique<Resource>();
    res->use();
    // Automatically deleted when scope exits!
    return 0;
}

#include <iostream>
#include <vector>
#include <utility>

class Buffer {
private:
    size_t size;
    int* data;
public:
    // Constructor
    Buffer(size_t s) : size(s), data(new int[s]) {
        std::cout << "Buffer created (" << size << " ints)\n";
    }
    // Destructor
    ~Buffer() { delete[] data; }

    // Move Constructor (Transfers ownership, zero copying)
    Buffer(Buffer&& other) noexcept : size(other.size), data(other.data) {
        other.size = 0;
        other.data = nullptr;
        std::cout << "Buffer MOVED!\n";
    }
};

int main() {
    std::cout << "=== 07: Move Semantics & Rvalues (std::move) ===\n";
    Buffer b1(1000);
    Buffer b2 = std::move(b1); // Move constructor called
    return 0;
}

#include <iostream>
#include <memory>

class Base {
public:
    virtual void speak() const { std::cout << "Base sound\n"; }
    // Golden Rule: Always provide virtual destructor in polymorphic base classes!
    virtual ~Base() = default;
};

class Derived : public Base {
public:
    void speak() const override { std::cout << "Derived sound (Vtable resolved!)\n"; }
};

int main() {
    std::cout << "=== 08: OOP, Polymorphism & Vtables ===\n";
    std::unique_ptr<Base> obj = std::make_unique<Derived>();
    obj->speak(); // Dispatches through Vtable to Derived::speak
    return 0;
}

