#include <iostream>
#include <vector>
#include <ranges>
#include <algorithm>

int main() {
    std::cout << "=== 11: STL Algorithms & C++20 Ranges ===\n";

    std::vector<int> nums = {1, 2, 3, 4, 5, 6};
    // C++20 Ranges pipeline composition
    auto even_squares = nums 
        | std::views::filter([](int n) { return n % 2 == 0; })
        | std::views::transform([](int n) { return n * n; });

    for (int n : even_squares) {
        std::cout << n << " ";
    }
    std::cout << "\n";
    return 0;
}

#include <iostream>
#include <optional>

std::optional<int> safeDivide(int a, int b) {
    if (b == 0) return std::nullopt;
    return a / b;
}

int main() {
    std::cout << "=== 12: Modern Error Handling (std::optional, std::expected) ===\n";
    auto res = safeDivide(10, 2);
    if (res.has_value()) {
        std::cout << "Division result: " << *res << "\n";
    }
    return 0;
}

#include <iostream>
#include <thread>
#include <mutex>
#include <atomic>

std::atomic<int> counter{0};

void increment() {
    for (int i = 0; i < 1000; ++i) {
        counter.fetch_add(1, std::memory_order_relaxed);
    }
}

int main() {
    std::cout << "=== 13: Multithreading & Atomics ===\n";
    std::jthread t1(increment);
    std::jthread t2(increment);
    t1.join();
    t2.join();
    std::cout << "Atomic counter final value: " << counter.load() << "\n";
    return 0;
}

